    "title": "马原·第四章 单选 第1题",
    "content": "商品具有使用价值和价值两个因素或两种属性，是使用价值和价值的矛盾统一体。决定商品交换的比例的，不是商品的使用价值，而是价值，这是因为\nA.使用价值无法用来衡量\nB.价值在质上是相同的\nC.使用价值和价值二者不可兼得\nD.价值是交换价值的物质承担者",
