    "title": "马原·第四章 单选 第21题",
    "content": "商品的使用价值和价值的矛盾、生产商品的具体劳动和抽象劳动的矛盾，根源于\nA.生产社会化和生产资料资本主义私人占有之间的矛盾\nB.商品和货币的矛盾\nC.简单劳动和复杂劳动的矛盾\nD.私人劳动和社会劳动的矛盾",
    "mistakeType": "概念不清",
