    "chapterId": "my_ch4",
    "chapterName": "马原·第四章",
    "sectionId": "my_ch4_s",
    "sectionName": "第四章·单选",
    "title": "马原·第四章 单选 第34题",
    "content": "在不同的剥削制度下，劳动者与生产资料的结合方式不同。在资本主义制度下，资本家与工人的关系是\nA.掌握先进技术和生产资料的资本家对工人的完全占有\nB.工人在丧失土地和生产资料之后不得不对资本家的人身依附\nC.基于劳动者人身自由基础上的“平等”关系\nD.基于资产阶级“社会契约论”基础上的私人占有关系",
