    "title": "马原·第四章 单选 第51题",
    "content": "在英国，从14世纪末到18世纪中叶这段时期，政府曾经颁布过各种劳工法令，强迫工人延长工作日。在18世纪后期至19世纪上半叶，资本家依然强迫工人每日劳动12、14、16个小时，有的时候甚至达到18个小时以上。通过这种方式资本家获得的是\nA.超额剩余价值\nB.相对剩余价值\nC.绝对剩余价值\nD.垄断剩余价值",
