    "title": "马原·第四章 单选 第52题",
    "content": "某资本家经营的企业原工作时间为每天8小时，其中必要劳动时间为4小时，剩余劳动时间也为4小时。如果分别采用绝对剩余价值生产方法和相对剩余价值生产方法，使剩余劳动时间各延长2小时，则它们的剩余价值率分别应为\nA.150%；200%\nB.200%；300%\nC.150%；300%\nD.125%；200%",
