    "chapterName": "马原·第四章",
    "sectionId": "my_ch4_s",
    "sectionName": "第四章·单选",
    "title": "马原·第四章 单选 第55题",
    "content": "在生产技术水平不断提高的条件下，随着资本积累的增长，必然伴随着资本的积聚和集中，使个别资本的规模日益增大。资本集中是指个别资本通过结合而形成较大的资本。资本集中最强有力的杠杆是\nA.竞争和信用\nB.投资和借贷\nC.资本原始积累\nD.生产自动化",
