    "title": "马原·第四章 单选 第58题",
    "content": "社会生产是连续不断地进行的，这种连续不断重复的生产就是再生产。社会再生产的核心问题是\nA.两大部类在总量上的比例问题\nB.社会总产品的价值补偿和实物补偿问题\nC.工资与剩余价值的分配问题\nD.劳动过程和价值增殖过程的统一问题",
