    "chapterName": "马原·第四章",
    "sectionId": "my_ch4_s",
    "sectionName": "第四章·单选",
    "title": "马原·第四章 单选 第60题",
    "content": "利润平均化规律，反映了在瓜分剩余价值上，资本家之间虽然存在竞争和矛盾，但在加强对工人阶级的剥削以榨取更大量的剩余价值这一点上，资本家之间有着共同的阶级利益。平均利润的出现是\nA.同一部门内不同企业之间竞争的结果\nB.不同部门之间竞争的结果\nC.国际上同类企业之间竞争的结果\nD.不同行业之间工人联合斗争的结果",
