    "sectionName": "第四章·单选",
    "title": "马原·第四章 单选 第61题",
    "content": "随着资本主义大工业的出现和发展，价值规律的实现形式也发生了变化，商品不再以价值而是以生产价格为基础进行交换。作为商品价值的转化形式，生产价格是\nA.生产成本与平均利润之和\nB.生产中实际耗费的不变资本和可变资本之和\nC.商品价值与劳动力成本之和\nD.所用资本与所费资本之和",
