    "title": "马原·第四章 单选 第62题",
    "content": "在资本主义社会里，资本家雇佣工人进行劳动并支付相应的工资。资本主义工资的本质是\nA.工人全部劳动的报酬\nB.劳动力的价值或价格\nC.资本家预付的不变资本的一部分\nD.工人所创造的剩余价值的一部分",
