    "title": "马原·第四章 单选 第63题",
    "content": "资本主义制度下的工资之所以掩盖了资本主义剥削关系，是因为\nA.工资表现为“劳动的价格”\nB.工资表现为劳动力的价值\nC.工资模糊了个别劳动时间和社会必要劳动时间的界限\nD.工资的价值只计算了转移到新产品中去的那一部分",
