    "content": "资本主义经济危机爆发的根本原因是资本主义的基本矛盾。经济危机的抽象的一般的可能性首先是由\nA.社会的绝对的消费能力引起的\nB.货币作为流通手段和支付手段引起的\nC.商品价格和价值之间量的不一致引起的\nD.社会总产品两大部类比例失衡引起的",
