    "content": "马克思指出：“资本主义生产方式占统治地位的社会的财富，表现为‘庞大的商品堆积’,单个的商品表现为这种财富的元素形式。”商品是\nA.用来交换的、能满足人们某种需要的劳动产品\nB.使用价值和价值的矛盾统一体\nC.价值和交换价值的矛盾统一体\nD.伴随人类社会始终的",
