    "title": "马原·第四章 多选 第8题",
    "content": "商品的价值形式是不断发展演变的。从历史上看，商品价值形式的发展经历了四个阶段，即简单的或偶然的价值形式、总和的或扩大的价值形式、一般价值形式、货币形式。由此可见\nA.货币是在长期交换过程中形成的固定充当一般等价物的商品\nB.货币是商品经济内在矛盾发展的产物\nC.货币的本质体现一种社会关系\nD.货币的出现标志着简单商品生产发展到资本主义商品生产的新阶段",
