    "title": "马原·第四章 多选 第22题",
    "content": "在资本主义条件下，资本家剥削剩余价值具有隐蔽性。马克思分析揭示了剩余价值的真正来源，阐明了资本的实质。以下选项中属于价值源泉的有\nA.劳动力商品的使用价值\nB.雇佣工人的劳动\nC.全部预付资本中的流动资本部分\nD.生产资料的价值",
