    "chapterId": "my_ch4",
    "chapterName": "马原·第四章",
    "sectionId": "my_ch4_m",
    "sectionName": "第四章·多选",
    "title": "马原·第四章 多选 第23题",
    "content": "根据资本在剩余价值生产中所起的不同作用，可以将资本划分为不变资本与可变资本。以下说法正确的有\nA.可变资本的价值是由工人的劳动再生产出来的\nB.不变资本就是固定资本\nC.这种划分为确定资本家对雇佣劳动者的剥削程度提供了科学依据\nD.剩余价值全部是由可变资本创造的",
