    "sectionId": "my_ch4_m",
    "sectionName": "第四章·多选",
    "title": "马原·第四章 多选 第25题",
    "content": "在资本主义发展的初期，资本家主要依靠绝对剩余价值生产来提高剥削程度。绝对剩余价值生产采取的方法有\nA.延长工作日的长度\nB.提高工人的劳动强度\nC.缩短必要劳动时间\nD.降低劳动力的价值",
