    "chapterId": "my_ch5",
    "chapterName": "马原·第五章",
    "sectionId": "my_ch5_m",
    "sectionName": "第五章·多选",
    "title": "马原·第五章 多选 第13题",
    "content": "垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断统治。垄断资本向世界范围扩展的基本形式有\nA.技术资本输出\nB.借贷资本输出\nC.生产资本输出\nD.商品资本输出",
