    "content": "第二次世界大战后资本主义出现的变化原因是多方面的，主要有\nA.科学技术革命和生产力的发展，是资本主义发生变化的根本推动力量\nB.工人阶级争取自身权利和利益的斗争，是推动资本主义发生变化的重要力量\nC.社会主义制度初步显示的优越性对资本主义产生了重要影响\nD.主张改良主义的政党对资本主义制度的改革触动了资本主义基本经济制度",
