    "content": "进入21世纪以来，资本主义呈现出一些新变化、新特征。国际金融垄断资本主义影响日益显现，国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征，这表现在\nA.金融垄断寡头化\nB.金融垄断国际化\nC.经济虚拟化\nD.产业空心化",
