    "title": "马原·第五章 多选 第30题",
    "content": "当前，百年变局加速演进，国际格局和国际体系深刻调整，全球治理体系深刻变革，国际力量对比正在发生近代以来最具革命性的变化，世界进入新的动荡变革期。资本主义社会问题加速积聚，资本主义国家内部的矛盾和冲突日益明显，表现为\nA.经济发展失调\nB.政治体制失灵\nC.社会融合机制失效\nD.生态领域失控",
