    "title": "马原·第六章 单选 第3题",
    "content": "空想社会主义的发展经历了三个阶段，其中成为科学社会主义的直接思想来源的是\nA.16—17世纪的早期空想社会主义\nB.18世纪的空想平均共产主义\nC.19世纪初期批判的空想社会主义\nD.20世纪的空想社会主义",
