    "title": "马原·第六章 单选 第6题",
    "content": "1921年3月，俄共（布）召开十大，毅然决定从战时共产主义政策过渡到新经济政策。新经济政策的主要特征是\nA.开展农业合作化\nB.发展商品经济\nC.优先发展重工业\nD.多种经济成分并存",
