    "title": "马原·第六章 多选 第2题",
    "content": "19世纪初期以圣西门、傅立叶、欧文为代表的批判的空想社会主义者，他们\nA.在理论上致力于对社会制度的分析\nB.对资本主义旧制度的辛辣批判，包含着许多切中要害的见解\nC.对社会主义新制度的描绘，闪烁着诸多天才的火花\nD.阐明了资本主义制度下雇佣奴隶制的本质，为启发工人觉悟提供了极为宝贵的材料",
    "mistakeType": "概念不清",
