    "title": "马原·第六章 多选 第7题",
    "content": "1921年3月，俄共（布）召开十大，毅然决定从战时共产主义政策过渡到实行新经济政策。俄共（布）十大决定实行新经济政策，是因为\nA.国家从战争转入和平经济建设时期，战时共产主义政策无法调动生产者尤其是农民的积极性\nB.国民经济已濒临崩溃，国内发生严重的经济和政治危机\nC.如不改变政策，执政党将会失去广大群众，丢掉阶级基础\nD.需要为实行农业集体化摸索经验",
