    "sectionName": "第六章·多选",
    "title": "马原·第六章 多选 第9题",
    "content": "1921年3月，俄共（布）召开十大，毅然决定从战时共产主义政策过渡到实行以发展商品经济为主要特征的新经济政策。新经济政策的实施\nA.完成了农业合作化，在广大农村建立起了社会主义的制度基础\nB.扭转了国家的严重危机，改善了工人、农民和其他劳动者的物质文化生活\nC.活跃了苏维埃的城乡经济，发展了生产，大大加强了苏维埃的社会主义经济基础\nD.标志着苏联模式开始形成",
