    "sectionName": "第一章·单选",
    "title": "史纲·第一章 单选 第3题",
    "content": "中国近代社会的两对主要矛盾是互相交织的，而帝国主义和中华民族的矛盾是最主要的矛盾。但是，在某个阶段、某个时期，阶级矛盾也会上升为主要矛盾，民族矛盾退居次要地位。以下根源于阶级矛盾上升为主要矛盾的事件是\nA.义和团运动\nB.甲午战争\nC.鸦片战争\nD.辛亥革命",
