    "content": "资本-帝国主义侵略、压迫中国人民的过程，同时也是中国人民反抗它们的侵略、压迫的过程。中国近代史上中国人民第一次大规模的反侵略武装斗争是\nA.三元里人民的抗英斗争\nB.太平天国的抗击洋枪队斗争\nC.台湾高山族人民的抗日斗争\nD.义和团的抗击八国联军斗争",
