    "title": "史纲·第二章 单选 第3题",
    "content": "洋务派继承了魏源“师夷长技以制夷”的思想，提出“自强”“求富”的主张，通过所掌握的国家权力集中力量优先发展\nA.官办企业\nB.民用企业\nC.军事工业\nD.邮政铁路",
