    "chapterId": "sg_ch6",
    "chapterName": "史纲·第六章",
    "sectionId": "sg_ch6_s",
    "sectionName": "第六章·单选",
    "title": "史纲·第六章 单选 第6题",
    "content": "1937年8月22日至25日，中共中央在陕北洛川召开政治局扩大会议(洛川会议),通过了《中国共产党抗日救国十大纲领》和《中共中央关于目前形势与党的任务的决定》,这标志着\nA.党的“逼蒋抗日”总方针的明确提出\nB.党确立了建立广泛的抗日民族统一战线的策略\nC.党制定了关于根据地建设的基本方针\nD.党的全面抗战路线的正式形成",
    "mistakeType": "概念不清",
