    "chapterId": "sg_ch6",
    "chapterName": "史纲·第六章",
    "sectionId": "sg_ch6_s",
    "sectionName": "第六章·单选",
    "title": "史纲·第六章 单选 第17题",
    "content": "中国人民抗日战争的胜利，是近代以来中国人民反抗外敌入侵第一次取得完全胜利的民族解放斗争。抗日战争取得胜利的决定因素是\nA.中国共产党的中流砥柱作用\nB.以爱国主义为核心的民族精神\nC.全民族抗战\nD.坚持持久战方针",
    "mistakeType": "概念不清",
    "importance": 4,
