    "content": "为了抗日民族统一战线的坚持、扩大和巩固，中国共产党制定了“发展进步势力，争取中间势力，孤立顽固势力”的策略总方针。同顽固派作斗争必须坚持\nA.有节\nB.有理\nC.有利\nD.有力",
