    "title": "史纲·第八章 多选 第1题",
    "content": "社会主义革命和建设时期，党面临的主要任务是\nA.实现从新民主主义到社会主义的转变\nB.进行社会主义革命\nC.推进社会主义建设\nD.为实现中华民族伟大复兴奠定根本政治前提和制度基础",
