    "chapterId": "sg_ch8",
    "chapterName": "史纲·第八章",
    "sectionId": "sg_ch8_m",
    "sectionName": "第八章·多选",
    "title": "史纲·第八章 多选 第6题",
    "content": "新中国成立后的最初三年，在着重完成民主革命的遗留任务的同时，社会主义革命的任务实际上也已经开始实行了。以下属于开始实行社会主义革命任务表现的有\nA.在全国开展镇压反革命的运动\nB.没收官僚资本，确立社会主义国营经济的领导地位\nC.开始将资本主义纳入国家资本主义轨道\nD.在新解放区进行土改",
