    "chapterName": "史纲·第八章",
    "sectionId": "sg_ch8_m",
    "sectionName": "第八章·多选",
    "title": "史纲·第八章 多选 第8题",
    "content": "在进行社会主义改造、向社会主义过渡的进程中，中国共产党积累了丰富的历史经验，包括坚持社会主义工业化建设与社会主义改造同时并举，采取积极引导、逐步过渡的方式及用和平方法进行改造。在以下逐步过渡的方式中，在性质上属于半社会主义性质的形式是\nA.手工业供销合作社\nB.全行业的公私合营\nC.初级农业生产合作社\nD.个别企业的公私合营",
    "mistakeType": "概念不清",
