    "content": "2025年是“十四五”规划收官之年。科学制定和接续实施五年规划，是我们党治国理政一条重要经验，也是中国特色社会主义一个重要政治优势。从“一五”到“十四五”，一以贯之的主题是\nA.不断提高人民生活水平\nB.不断壮大我国综合国力\nC.不断推进中华民族伟大复兴\nD.把我国建设成为社会主义现代化国家",
