    "content": "为掩护战友身负重伤的扫雷英雄“杜富国”，“用爱照亮山区女孩人生梦想的教育燃灯者”张桂梅，“为莫高窟研究保护倾尽一生的敦煌女儿”樊锦诗，“60多年深藏功名的战斗英雄”张富清，以及在黄山风景区分别从事环卫保洁和迎客松守护工作的“中国好人”李培生、胡晓春等平凡英雄，他们最可贵的地方就是在平凡的工作中创造了不平凡的业绩。他们的事迹告诉我们，评价人生价值的根本尺度，是看一个人的\nA.劳动以及通过劳动对社会和他人作出的贡献\nB.个人社会地位的高低\nC.个人成绩的大小\nD.实践活动是否符合社会发展的客观规律，是否促进了历史的进步",
    "mistakeType": "概念不清",
