    "title": "思修·第二章 单选 第2题",
    "content": "走向绞刑架的李大钊，发出了“共产主义在中国必然得到光辉的胜利”的坚贞誓言。面对敌人屠刀的夏明翰，写下“砍头不要紧，只要主义真。杀了夏明翰，还有后来人”的雄壮诗篇。面对敌人6天内9次劝降，瞿秋白作出了“人爱自己的历史，比鸟爱自己的翅膀更厉害，请勿撕破我的历史”的铿锵回答。理想信念是精神之“钙”。信念是认知、情感和意志的有机统一体。信念的特征包括①超越性②支撑性③执着性④多样性\nA.①②③\nB.①②④\nC.②③④\nD.①③④",
    "mistakeType": "概念不清",
    "importance": 4,
