    "sectionId": "sx_ch2_m",
    "sectionName": "第二章·多选",
    "title": "思修·第二章 多选 第6题",
    "content": "习近平在国家勋章和国家荣誉称号颁授仪式上的讲话中强调，要胸怀强国之志，以国家富强为念，以人民幸福为盼，忠心爱国、矢志报国，把个人小我融入国家大我，在为国尽责、为民服务中实现个人价值、展现个人风采。在整个理想体系中，社会理想是最根本、最重要的，而个人理想则从属于社会理想。这是因为\nA.个人理想的确立要以社会理想为导向\nB.个人理想的实现依赖于社会理想的指引\nC.从根本上说个人理想是由社会理想规定的\nD.社会理想是个人理想的叠加",
