    "content": "2023年10月24日，第十四届全国人大常委会第六次会议表决通过了《中华人民共和国爱国主义教育法》，自2024年1月1日起施行。制定该法的目的是加强新时代爱国主义教育，传承和弘扬爱国主义精神，凝聚全面建设社会主义现代化国家、全面推进中华民族伟大复兴的磅礴力量。爱国主义是中华民族精神的核心。中国特色社会主义进入新时代，实现中华民族伟大复兴的中国梦是新时代爱国主义的鲜明主题。大力弘扬新时代爱国主义，必须\nA.坚持爱国爱党爱社会主义相统一\nB.维护祖国统一和民族团结\nC.尊重和传承中华民族历史文化\nD.坚持立足中国又面向世界",
