    "content": "近年来，《中国汉字听写大会》《中国诗词大会》《中国成语大会》《经典咏流传》《朗读者》等节目广受欢迎。这类节目符合国情、接地气，从中华历史和优秀传统文化资源中汲取养分，增进了人们对祖国悠久历史、深厚文化的理解和接受，是人们爱国主义情感培育和发展的重要条件。中华优秀传统文化是\nA.中华民族精神的核心\nB.中华民族得以延续的文化基因\nC.我们在世界文化激荡中站稳脚跟的根基\nD.中华民族的精神命脉",
