    "title": "思修·第四章 多选 第1题",
    "content": "人类社会发展的历史表明，对一个民族、一个国家来说，最持久、最深沉的力量是全社会共同认可的核心价值观。核心价值观\nA.承载着一个民族、一个国家的精神追求\nB.体现着一个社会评判是非曲直的价值标准\nC.是一定社会形态、社会性质的集中体现，在整个上层建筑中处于主导地位\nD.体现着社会制度的阶级属性、社会运行的基本原则和社会发展的基本方向",
