    "title": "思修·第四章 多选 第3题",
    "content": "社会主义核心价值观的基本内容是富强、民主、文明、和谐，自由、平等、公正、法治，爱国、敬业、诚信、友善。自由、平等、公正、法治回答了建设什么样的社会的重大问题，与实现国家治理体系和治理能力现代化的要求相契合，揭示了社会主义社会发展的价值取向。以下选项内容正确的有\nA.自由是社会活力之源，是社会主义的价值理想\nB.平等是人类追求的普世价值\nC.公正是人类社会进步的标尺，是社会主义制度的本质要求\nD.法治是人类政治文明的重要成果，是现代社会的主要特征",
