    "content": "国家艺术基金资助项目、新编历史晋剧《日昇昌票号》里有这样的情节：当饥寒交迫的魏老太拿着被水浸过的汇票来兑银子，伙计难辨数额怎么办？日昇昌票号大掌柜雷履泰责人详查账目底簿，当机立断，兑！当伙计忽略差价少给客商兑了七两八钱银子怎么办？雷履泰斩钉截铁，补齐！正是靠着这种诚信精神，日昇昌票号实现了分号遍布全国几十个城市、商埠重镇，以\"汇通天下\"著称于世。诚信是社会主义核心价值观的重要内容，是\nA.个人立身处世的基本价值规范\nB.社会存续发展的重要价值基石\nC.社会主义职业道德的基本规范之一\nD.中华传统美德的根本要求",
