    "title": "思修·第五章 多选 第13题",
    "content": "2024年10月，习近平在福建省漳州市东山县考察时，来到谷文昌纪念馆，强调\"学习谷文昌同志，不仅要高山仰止，还要见贤思齐，像他那样做人、为政\"。\"见贤思齐\"是中华传统美德中强调道德修养，注重道德践履的体现。中国古代的思想家大都认为，在修身养性的过程中，最重要的就是要使社会的道德原则和规范转换为自身的思想品德和行为实践，通过切磋践履不断养成良好的道德习惯，形成完善的道德人格。以下选项中，体现了中华传统美德强调道德修养，注重道德践履的有\nA.\"修己\"\"克己\"和\"慎独\"\nB.\"善养吾浩然之气\"\nC.\"明于庶物，察于人伦\"\nD.\"察色修身\"",
    "mistakeType": "概念不清",
    "importance": 4,
