    "title": "思修·第五章 多选 第14题",
    "content": "2024年10月17日，习近平来到安徽省安庆桐城市考察。地处城中的六尺巷，因清代大学士张英与邻居吴家互相退让三尺地基而成，是中国邻里和谐礼让的典范。习近平指出，人民内部矛盾要用调解的办法解决。六尺巷体现了先人化解矛盾的历史智慧，要作为弘扬中华优秀传统文化的教育场所，发挥好中华民族讲求礼让、以和为贵传统美德的作用，营造安居乐业的和谐社会环境。推崇仁爱、崇尚和谐是中华民族的优良传统和高尚品德。以下选项中，体现了中华传统美德推崇仁爱原则，注重以和为贵的有\nA.\"己欲立而立人，己欲达而达人\"\nB.\"亲亲而仁民，仁民而爱物\"\nC.\"仁、义、礼、智、信\"\nD.\"兼相爱，交相利\"",
    "mistakeType": "概念不清",
    "importance": 4,
