    "content": "\"怒发冲冠，凭栏处、潇潇雨歇。\"抗金名将岳飞留给我们的，除了气吞山河的壮烈，莫须冤死的悲戚，还有一段精忠报国的热血家训。习近平曾多次讲过岳母刺字的故事，强调家风是社会风气的重要组成部分，父母应引导孩子成为对国家和人民有用的人。之所以要注重家教、家风，是因为\nA.家庭是人生的第一个课堂，父母是孩子的第一任老师\nB.良好的家风，对家庭成员的个人修养产生着重要的作用\nC.良好的家风，对整个社会道德风尚的形成产生着重要的影响\nD.家教是新时代公民道德建设的重点任务",
