    "chapterId": "xxs_ch6",
    "chapterName": "新思想·第六章",
    "sectionId": "xxs_ch6_s",
    "sectionName": "第六章·单选",
    "title": "新思想·第六章 单选 第3题",
    "content": "高质量发展是新时代我国经济社会发展的鲜明主题，是全面建设社会主义现代化国家的首要任务。推动高质量发展的主线是\nA.改革创新\nB.实施扩大内需战略\nC.深化供给侧结构性改革\nD.加快构建新发展格局",
    "mistakeType": "概念不清",
