    "chapterId": "xxs_ch6",
    "chapterName": "新思想·第六章",
    "sectionId": "xxs_ch6_s",
    "sectionName": "第六章·单选",
    "title": "新思想·第六章 单选 第4题",
    "content": "高质量发展是全面建设社会主义现代化国家的首要任务。推动高质量发展的战略基点是\nA.加快实现高水平科技自立自强\nB.加快构建新发展格局\nC.推进农业现代化\nD.更好统质效质的有效提升和量的合理增长",
