    "chapterName": "新思想·第六章",
    "sectionId": "xxs_ch6_s",
    "sectionName": "第六章·单选",
    "title": "新思想·第六章 单选 第7题",
    "content": "构建新发展格局，是根据我国发展阶段、发展环境、条件变化，特别是基于我国比较优势变化，审时度势作出的重大决策，是关系我国发展全局的重大战略任务。构建新发展格局最本质的特征是\nA.实现高水平的自立自强\nB.推动实施扩大内需战略同深化供给侧结构性改革有机结合\nC.推动产业链供应链优化升级\nD.建设现代化经济体系",
    "mistakeType": "概念不清",
