    "chapterName": "新思想·第六章",
    "sectionId": "xxs_ch6_s",
    "sectionName": "第六章·单选",
    "title": "新思想·第六章 单选 第8题",
    "content": "构建新发展格局是事关全局的系统性、深层次变革，是立足当前、着眼长远的战略谋划，是适应我国发展新阶段要求、塑造国际合作和竞争新优势的必然选择。构建新发展格局的重要前提和保障是\nA.充分挖掘内需潜力\nB.夯实我国经济发展的根基\nC.促进区域协调发展\nD.牢牢守住安全发展这条底线",
    "mistakeType": "概念不清",
