    "chapterName": "新思想·第六章",
    "sectionId": "xxs_ch6_s",
    "sectionName": "第六章·单选",
    "title": "新思想·第六章 单选 第10题",
    "content": "新质生产力由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生，以劳动者、劳动资料、劳动对象及其优化组合的跃升为基本内涵。新质生产力的核心标志是\nA.全要素生产率大幅提升\nB.创新和质优\nC.稳定的产业链供应链\nD.催生新产业、新模式、新动能",
