    "chapterName": "新思想·第六章",
    "sectionId": "xxs_ch6_s",
    "sectionName": "第六章·单选",
    "title": "新思想·第六章 单选 第12题",
    "content": "脱贫摘帽不是终点，而是新生活、新奋斗的起点。接下来要做好乡村振兴这篇大文章，让乡亲们生活越来越美好。实施乡村振兴战略的总方针是\nA.农业农村现代化\nB.坚持农业农村优先发展\nC.产业兴旺、生态宜居、乡风文明、治理有效、生活富裕\nD.建立健全城乡融合发展体制机制和政策体系",
