    "chapterName": "新思想·第六章",
    "sectionId": "xxs_ch6_s",
    "sectionName": "第六章·单选",
    "title": "新思想·第六章 单选 第13题",
    "content": "我国发展最大的不平衡是城乡发展不平衡，最大的不充分是农村发展不充分。必须坚持把解决好“三农”问题作为全党工作重中之重，扎实推进乡村全面振兴。推进乡村全面振兴的基础是\nA.农业农村现代化\nB.发展乡村特色产业\nC.持续深化农村科技和改革创新\nD.建立健全城乡融合发展体制",
