    "title": "新思想·第六章 单选 第15题",
    "content": "城镇化是现代化的必由之路，是解决农业、农村、农民问题的重要途径，是推动区域协调发展的有力支撑，是扩大内需和促进产业升级的重要抓手。新型城镇化的首要任务是\nA.进一步深化户籍制度改革\nB.推进公共服务共建共享\nC.推进农业转移人口市民化\nD.强化产业分工协作",
