    "content": "创新、协调、绿色、开放、共享的新发展理念相互贯通、相互促进，是具有内在联系的集合体。以下说法正确的有\nA.创新发展注重的是解决发展动力问题\nB.绿色发展注重的是解决人与自然和谐共生问题\nC.开放发展注重的是解决发展内外联动问题\nD.共享发展注重的是解决发展不平衡问题",
