    "sectionName": "第六章·多选",
    "title": "新思想·第六章 多选 第5题",
    "content": "习近平提出，发展新质生产力是推动高质量发展的内在要求和重要着力点。关于新质生产力，以下理解正确的有\nA.战略性新兴产业、未来产业是发展新质生产力的主阵地\nB.传统产业通过转型升级，也能成为新质生产力的重要部分\nC.科技创新是发展新质生产力的核心要素\nD.发展新质生产力以劳动者、劳动资料、劳动对象及其优化组合的跃升为核心标志",
    "mistakeType": "概念不清",
    "importance": 4,
    "correction": "正确答案：ABC\n您的答案：ABCD",
    "createdAt": "2026-10-28T12:00:00.000Z",
