    "content": "公有制经济是全体人民的宝贵财富，公有制主体地位不能动摇，国有经济主导作用不能动摇，这是我国各族人民共享发展成果的制度性保证，也是巩固党的执政地位、坚持我国社会主义制度的重要保证。国有企业是\nA.中国特色社会主义的重要物质基础\nB.中国特色社会主义的政治基础\nC.我们党执政兴国的重要支柱\nD.我们党执政兴国的依靠力量",
