    "title": "新思想·第六章 多选 第9题",
    "content": "我国非公有制经济是改革开放以来在中国共产党的方针政策指引下发展起来的，我们要毫不动摇鼓励、支持、引导非公有制经济发展。非公有制经济是\nA.社会主义经济的重要组成部分和我国经济社会发展的重要基础\nB.国家税收的重要来源和就业创业的重要领域\nC.稳定经济的重要基础和金融发展的重要依托\nD.技术创新的重要主体和经济持续健康发展的重要力量",
