    "sectionName": "第六章·多选",
    "title": "新思想·第六章 多选 第10题",
    "content": "几十年来，关于对民营经济在改革开放和社会主义现代化建设事业中地位和作用的认识、党和国家对民营经济发展的方针政策，我们党理论和实践是一脉相承、与时俱进的。党和国家对民营经济发展的基本方针政策，概括起来就是\nA.非公有制经济是我国社会主义市场经济的重要组成部分，受宪法和法律保护\nB.毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展\nC.保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受到法律保护\nD.促进各种所有制经济优势互补、共同发展，促进非公有制经济健康发展和非公有制经济人士健康成长",
