    "title": "新思想·第六章 多选 第12题",
    "content": "纵深推进全国统一大市场建设，基本要求是“五统一、一开放”,即统一市场基础制度、统一市场基础设施、统一政府行为尺度、统一市场监管执法、统一要素资源市场，持续扩大对内对外开放。在“五统一、一开放”中，“统一政府行为尺度”的首次提出，意义重大。“统一政府行为尺度”有助于\nA.促进要素资源流动\nB.破解不同地区之间的过度“内卷”\nC.从根本上杜绝权力寻租和腐败行为\nD.为各类经营主体创造更公平的市场竞争环境",
