    "sectionName": "第八章·多选",
    "title": "新思想·第八章 多选 第12题",
    "content": "70多年来的实践充分证明，人民政协在人类政治制度发展史上具有独特政治价值，已经并将不断展现出旺盛生命力。人民政协\nA.作为多党派参政的国家权力机关，有利于贯彻民主集中制、保证国家政治生活既充满活力又安定有序\nB.作为最广泛的爱国统一战线组织，有利于最大限度把全体中华儿女的智慧和力量凝聚起来\nC.作为社会主义协商民主的重要渠道和专门协商机构，有利于促进科学决策、有效施策，提升国家治理效能\nD.作为中国共产党领导的政治组织，有利于完善人民当家作主的制度体系",
