    "sectionName": "第八章·多选",
    "title": "新思想·第八章 多选 第16题",
    "content": "统一战线是我国新民主主义革命的三大法宝之一。新时代，统一战线面临的时和势、肩负的使命和任务发生了重大变化，但统一战线仍然是重要法宝，我们要深刻理解发展壮大新时代爱国统一战线的重要意义。统一战线\nA.在维护国家主权、安全、发展利益上的作用更加重要\nB.在围绕中心、服务大局上的作用更加重要\nC.在增强党的阶级基础、扩大党的群众基础上的作用更加重要\nD.在团结国际社会共同反对霸权主义、单边主义的斗争中的作用更加重要",
