    "sectionId": "xxs_ch9_s",
    "sectionName": "第九章·单选",
    "title": "新思想·第九章 单选 第1题",
    "content": "习近平指出：“全面推进依法治国，必须走对路。如果路走错了，南辕北辙了，那再提什么要求和举措也都没有意义了。”我们党领导人民长期探索走出的中国特色社会主义法治道路，是全面依法治国的唯一正确道路。中国特色社会主义法治之魂是\nA.依法治国和以德治国相结合\nB.以人民为中心\nC.党的领导\nD.法律面前人人平等",
