    "title": "新思想·第九章 单选 第3题",
    "content": "走中国特色社会主义法治道路，必须坚持法律面前人人平等。平等是\nA.推进全面依法治国的根本目的\nB.我们的法治同西方资本主义国家的法治最大的区别\nC.社会主义法律的基本属性\nD.全面依法治国的关键",
