    "title": "新思想·第九章 单选 第4题",
    "content": "全面推进依法治国涉及很多方面，在实际工作中必须有一个总揽全局、牵引各方的总抓手，这个总抓手就是\nA.建设中国特色社会主义法治体系\nB.建设社会主义法治国家\nC.坚持依法治国、依法执政、依法行政共同推进\nD.坚持法治国家、法治政府、法治社会一体建设",
