    "chapterId": "xxs_ch9",
    "chapterName": "新思想·第九章",
    "sectionId": "xxs_ch9_s",
    "sectionName": "第九章·单选",
    "title": "新思想·第九章 单选 第6题",
    "content": "全面依法治国是国家治理的一场深刻革命，关系党执政兴国，关系人民幸福安康，关系党和国家长治久安。全面依法治国的重点任务和主体工程是\nA.法治国家建设\nB.法治政府建设\nC.法治社会建设\nD.依法行政",
