    "chapterId": "xxs_ch9",
    "chapterName": "新思想·第九章",
    "sectionId": "xxs_ch9_m",
    "sectionName": "第九章·多选",
    "title": "新思想·第九章 多选 第1题",
    "content": "法律是治国之重器，法治是国家治理体系和治理能力的重要依托。历史和现实告诉我们，法治兴则国兴，法治强则国强。全面依法治国，是\nA.完善和发展中国特色社会主义制度的重要方面\nB.推进国家治理体系和治理能力现代化的重要方面\nC.坚持和发展中国特色社会主义的本质要求\nD.坚持和发展中国特色社会主义的重要保障",
