    "content": "建设法治中国，是全面建设社会主义现代化国家的重要组成部分。加快建设法治中国，必须坚持统筹兼顾、把握重点、整体谋划，更加注重系统性、整体性、协同性。法治中国建设的工作布局是\nA.坚持依法治国、依法执政、依法行政共同推进\nB.坚持法治国家、法治政府、法治社会一体建设\nC.坚持科学立法、严格执法、公正司法、全民守法\nD.坚持统筹推进国内法治和涉外法治",
