    "sectionName": "第十章·单选",
    "title": "新思想·第十章 单选 第5题",
    "content": "中华文明具有突出的连续性，是世界上唯一绵延不断且以国家形态发展至今的伟大文明。中华文明的连续性，从根本上决定了\nA.国家统一永远是中国核心利益的核心\nB.国土不可分、国家不可乱、民族不可散、文明不可断的共同信念\nC.中华民族不惧新挑战、勇于接受新事物的无畏品格\nD.中华民族必然走自己的路",
