    "chapterId": "xxs_ch10",
    "chapterName": "新思想·第十章",
    "sectionId": "xxs_ch10_s",
    "sectionName": "第十章·单选",
    "title": "新思想·第十章 单选 第6题",
    "content": "随着我国社会主要矛盾的转化，人民对美好生活的向往越来越强烈，对精神文化生活更加看重，文化需求高品质、个性化的特点更加明显。满足人民精神文化需求、保障人民文化权益的基本途径是\nA.繁荣发展文化事业和文化产业\nB.推动中华优秀传统文化创造性转化、创新性发展\nC.提升国家文化软实力\nD.保护好、传承好文化遗产",
