    "chapterId": "xxs_ch10",
    "chapterName": "新思想·第十章",
    "sectionId": "xxs_ch10_m",
    "sectionName": "第十章·多选",
    "title": "新思想·第十章 多选 第9题",
    "content": "海纳百川，有容乃大。文明的繁荣、人类的进步，离不开求同存异、开放包容，离不开文明交流、互学互鉴。中华文明自古就以开放包容闻名于世。中华文明具有突出的包容性，从根本上决定了\nA.中华民族交往交流交融的历史取向\nB.中国各宗教信仰多元并存的和谐格局\nC.中华文化对世界文明兼收并蓄的开放胸怀\nD.中国不断追求文明交流互鉴而不搞文化霸权",
