    "title": "新思想·第十三章 单选 第5题",
    "content": "构建新安全格局是全面贯彻落实总体国家安全观的重大举措。构建统筹各领域安全的新安全格局的主阵地、主战场是\nA.维护意识形态安全\nB.维护制度安全\nC.维护政权安全\nD.维护重点领域国家安全",
