    "sectionId": "xxs_ch14_m",
    "sectionName": "第十四章·多选",
    "title": "新思想·第十四章 多选 第2题",
    "content": "进入新时代，以习近平同志为核心的党中央着眼实现中华民族伟大复兴这个国家和民族最高利益，对人民军队使命任务作出新定位、提出新要求，概括起来就是\nA.为巩固中国共产党领导和我国社会主义制度提供战略支撑\nB.为捍卫国家主权、统一和领土完整提供战略支撑\nC.为维护我国海外利益提供战略支撑\nD.为促进世界和平与发展提供战略支撑",
    "mistakeType": "概念不清",
