    "title": "新思想·第十五章 单选 第1题",
    "content": "“一国两制”是中国共产党领导人民实现祖国和平统一的伟大构想。“一国两制”方针的最高原则是\nA.维护国家主权、安全、发展利益\nB.实现祖国和平统一\nC.确保中华民族伟大复兴进程不被迟滞甚至中断\nD.政权必须掌握在爱国者手中",
    "mistakeType": "概念不清",
