    "title": "新思想·第十五章 多选 第3题",
    "content": "“一国两制”是党领导人民实现祖国和平统一的一项重要制度，是国家的一项基本国策。“一国两制”的根本宗旨是\nA.维护国家主权、安全、发展利益\nB.保持香港、澳门长期繁荣稳定\nC.维护台海和平稳定\nD.增强中华儿女对伟大祖国的认同感",
