    "sectionName": "第十五章·多选",
    "title": "新思想·第十五章 多选 第4题",
    "content": "“一国两制”方针是一个完整的体系。关于“一国”和“两制”的关系，以下说法正确的有\nA.“一国”是实行“两制”的前提和基础\nB.“两制”从属和派生于“一国”，并统一于“一国”之内\nC.“一国”是根，根深才能叶茂；“一国”是本，本固才能枝荣\nD.“一国”之内的“两制”等量齐观、比肩并列",
