    "title": "新思想·第十六章 单选 第1题",
    "content": "外交工作是党和国家工作全局的重要组成部分。中国特色大国外交牢牢把握的主线是\nA.服务民族复兴、促进人类进步\nB.相互尊重、合作共赢\nC.打造全球伙伴关系、维护多边主义\nD.维护世界和平、促进共同发展",
