    "title": "新思想·第十六章 单选 第3题",
    "content": "新时代新征程，要继续全面推进我国对外工作，不断开创中国特色大国外交新局面。我国对外工作的出发点和落脚点是\nA.坚定奉行独立自主的和平外交政策\nB.维护国家主权、安全、发展利益\nC.推动构建人类命运共同体\nD.坚持走和平发展道路",
