    "sectionName": "第十七章·多选",
    "title": "新思想·第十七章 多选 第4题",
    "content": "习近平在谈到作风建设时，曾引用泰山挑山工不敢在“快活三里”久留的故事。“快活三里”是泰山半腰的一段平路，游客喜欢在此歇脚，挑山工却不敢停留太久，因为他们知道休息时间长了，腿就会“发懒”，再上“十八盘”就更困难了。习近平引用这个故事，旨在告诫广大党员干部\nA.要警惕承平日久环境下追求安逸享乐而意志消沉\nB.作风建设永远在路上，不能有歇歇脚、松口气的念头\nC.作风建设必须一鼓作气，不能打持久战\nD.必须始终保持艰苦奋斗、负重前行的精神状态",
    "mistakeType": "概念不清",
    "importance": 4,
    "correction": "正确答案：ABD\n您的答案：ABC",
    "createdAt": "2026-10-28T12:00:00.000Z",
    "reviewCount": 0,
    "lastReviewAt": "",
    "mastered": false
